  end if;
end;
$do$;

-- ===== supabase/updates/20261204002600_friends_online_protests.sql =====
-- ===== idempotent copy of migrations/20261204002600_friends_online_protests.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 2600 · Friends online, finished campaigns leave the news after an hour
-- =============================================================================
-- * friends_json(): every friend carries "online" (active in the last social.onlineMinutes, default 10;
--   profiles.last_active_at is refreshed by require_player at most every 5 minutes) and "last_active_at";
--   online friends come first.
-- * protests_state(): a finished campaign stays visible for protests.visibleAfterMinutes (60) instead of a day.
-- Idempotent: runs unchanged as supabase/updates/20261204002600_friends_online_protests.sql.

create or replace function public.friends_json(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'friends', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level,
                                          'since', coalesce(f.responded_at, f.updated_at),
                                          'online', coalesce(p.last_active_at > public.game_now() - make_interval(
                                                      mins => coalesce(public.config_double('social', '{onlineMinutes}', 10), 10)::integer), false),
                                          'last_active_at', p.last_active_at)
                       order by coalesce(p.last_active_at > public.game_now() - make_interval(
                                  mins => coalesce(public.config_double('social', '{onlineMinutes}', 10), 10)::integer), false) desc,
                                lower(p.nickname), p.id)
        from public.friendships f
        join public.profiles p on p.id = case when f.requester_id = p_player then f.addressee_id else f.requester_id end
       where f.status = 'accepted' and p_player in (f.requester_id, f.addressee_id) and not p.is_deactivated), '[]'::jsonb),
    'incoming', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.requester_id
       where f.status = 'pending' and f.addressee_id = p_player and not p.is_deactivated), '[]'::jsonb),
    'outgoing', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.addressee_id
       where f.status = 'pending' and f.requester_id = p_player and not p.is_deactivated), '[]'::jsonb));
$$;

do $do$
declare
  v_def text := pg_get_functiondef('public.protests_state(uuid)'::regprocedure);
  v_old text := $t$x.resolved_at > now() - interval '1 day'$t$;
  v_new text := $t$x.resolved_at > now() - make_interval(mins => coalesce((public.protests_cfg() ->> 'visibleAfterMinutes')::integer, 60))$t$;
begin
  if position(v_old in v_def) > 0 then
    execute replace(v_def, v_old, v_new);
  end if;
end;
$do$;

-- ===== supabase/updates/20261204002700_missions_doable.sql =====
-- ===== idempotent copy of migrations/20261204002700_missions_doable.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 2700 · Missions are always doable; one-off mission: buy a property (ADR-154)
-- =============================================================================
-- mission_doable(player, key, metric) says whether a mission can still be finished by this player. missions_assign()
-- hands out only doable missions, and an active quick or milestone mission without progress that became impossible
-- (company full, home already bought) expires and makes room for another one.
-- m_home_first becomes "Kauf dir ein Grundstück": once, fixed 2500 base XP (5000 with the global multiplier),
-- shown first among the milestones once property is unlocked.
-- Idempotent: runs unchanged as supabase/updates/20261204002700_missions_doable.sql.

create or replace function public.mission_doable(p_player uuid, p_key text, p_metric text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  with co as (
    select pc.company_id, pc.ai_workers, c.max_employees, public.company_headcount(pc.company_id) as heads
      from public.player_companies pc join public.companies c on c.id = pc.company_id
     where pc.founder_id = p_player and pc.status = 'active'
     limit 1
  ), home as (
    select h.tier, coalesce((select (t ->> 'garageSlots')::integer
                               from jsonb_array_elements(public.config_jsonb('property', '{tiers}')) t
                              where t ->> 'key' = h.tier), 0) as garage,
           (select max(ord) from jsonb_array_elements(public.config_jsonb('property', '{tiers}')) with ordinality x(t, ord)) as top,
           (select ord from jsonb_array_elements(public.config_jsonb('property', '{tiers}')) with ordinality x(t, ord)
             where t ->> 'key' = h.tier) as pos
      from public.player_homes h where h.player_id = p_player
  )
  select case
    -- hiring needs a free place in the company; the "first" one only for who never had an AI worker
    when p_metric = 'ai_worker_hired' then
      exists (select 1 from co where co.heads < co.max_employees
                                 and (p_key <> 'm_first_ai_worker' or co.ai_workers = 0))
    when p_metric = 'job_posted' then
      exists (select 1 from co where co.heads < co.max_employees
                                 and (p_key <> 'm_first_posting'
                                      or not exists (select 1 from public.job_postings j where j.company_id = co.company_id)))
    -- property: buy one only without a home, move only below the top tier, cars only with a free garage place
    when p_metric = 'home_bought' then not exists (select 1 from home)
    when p_metric = 'home_upgraded' then exists (select 1 from home where home.pos < home.top)
    when p_metric = 'car_bought' then
      exists (select 1 from home where home.garage > (select count(*) from public.player_cars c where c.player_id = p_player))
    when p_metric in ('furniture_bought', 'furniture_placed') then exists (select 1 from home)
    -- "your first ..." only for who has not done it yet
    when p_key = 'm_first_skill' then not exists (select 1 from public.player_skills s where s.player_id = p_player)
    when p_key = 'm_first_move' then not exists (select 1 from public.company_moves m where m.started_by = p_player)
    when p_key = 'm_first_trade' then not exists (select 1 from public.trades t where t.player_id = p_player)
    when p_key = 'm_art_paint' then not exists (select 1 from public.artworks a where a.creator_id = p_player)
    when p_key = 'm_first_bond' then not exists (select 1 from public.trades t join public.securities s on s.id = t.security_id
                                                  where t.player_id = p_player and s.kind = 'bond')
    else true end;
$$;
revoke all on function public.mission_doable(uuid, text, text) from public, anon, authenticated;
grant execute on function public.mission_doable(uuid, text, text) to service_role;
comment on function public.mission_doable(uuid, text, text) is
  'Internal: whether the player can still finish a mission of this template (ADR-154).';

create or replace function public.missions_assign(p_player uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_prog     jsonb := coalesce(public.config_jsonb('progression'), '{}'::jsonb);
  v_now      timestamptz := public.game_now();
  v_today    date := (public.game_now() at time zone 'Europe/Berlin')::date;
  v_monday   date;
  v_level    integer;
  v_scale    double precision;
  v_xpscale  double precision;
  v_need     integer;
  v_n        integer := 0;
  v_kind     text;
  v_period   date;
  v_expires  timestamptz;
  v_rank     integer;
  t          record;
begin
  v_monday := v_today - (extract(isodow from v_today)::integer - 1);
  select p.level into v_level from public.profiles p where p.id = p_player for update;
  if v_level is null then
    return 0;
  end if;
  v_scale := least(public.cfg_num(v_prog, '{missionTargetScaleMax}', 5),
                   1 + public.cfg_num(v_prog, '{missionTargetScalePerLevel}', 0.2) * (v_level - 1));
  -- ADR-142: mission XP grows with the level, so missions stay worth it as levels need more XP
  v_xpscale := least(public.cfg_num(v_prog, '{missionXpScaleMax}', 1),
                     1 + public.cfg_num(v_prog, '{missionXpScalePerLevel}', 0) * (v_level - 1));

  -- ADR-154: a mission nobody can finish any more (the company is full, the home is bought) makes room for another
  update public.player_missions m set status = 'expired', expires_at = least(coalesce(m.expires_at, v_now), v_now)
    from public.mission_templates mt
   where mt.key = m.template_key and m.player_id = p_player and m.status = 'active' and m.progress = 0
     and m.kind in ('quick', 'milestone') and mt.mode <> 'state'
     and not public.mission_doable(p_player, mt.key, mt.metric);

  -- expire what ran out
  update public.player_missions set status = 'expired'
   where player_id = p_player and status in ('active', 'completed') and expires_at is not null and expires_at <= v_now;

  foreach v_kind in array array['quick', 'daily', 'weekly', 'milestone'] loop
    if v_kind = 'quick' then
      v_need := public.cfg_num(v_prog, '{xpSources,quickMission,active}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'quick' and m.status in ('active', 'completed'));
      v_period := v_today; v_expires := null;
    elsif v_kind = 'daily' then
      v_need := public.cfg_num(v_prog, '{xpSources,dailyMission,perDay}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'daily' and m.period_start = v_today);
      v_period := v_today; v_expires := ((v_today + 1)::timestamp) at time zone 'Europe/Berlin';
    elsif v_kind = 'weekly' then
      v_need := public.cfg_num(v_prog, '{xpSources,weeklyMission,perWeek}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'weekly' and m.period_start = v_monday);
      v_period := v_monday; v_expires := ((v_monday + 7)::timestamp) at time zone 'Europe/Berlin';
    else
      v_need := public.cfg_num(v_prog, '{xpSources,milestoneMission,visible}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'milestone' and m.status in ('active', 'completed'));
      v_period := date '2000-01-01'; v_expires := null;
    end if;
    continue when v_need <= 0;

    for t in
      select mt.*
        from public.mission_templates mt
       where mt.kind = v_kind and mt.mode is not null and mt.is_active
         and mt.min_level <= v_level
         and (not (mt.params ? 'unlock') or v_level >= public.unlock_level(mt.params ->> 'unlock'))
         and public.mission_requirement_ok(p_player, mt.params ->> 'requires')
         and public.mission_doable(p_player, mt.key, mt.metric)
         and not exists (select 1 from public.player_missions m
                          where m.player_id = p_player and m.template_key = mt.key
                            and (m.period_start = v_period
                                 or (v_kind = 'quick' and (m.status in ('active', 'completed') or m.created_at > v_now - interval '24 hours'))
                                 or v_kind = 'milestone'))
       order by case when v_kind = 'milestone' then mt.chain_order end,
                -ln(1 - random()) / greatest(mt.weight, 1)
       limit v_need
    loop
      if t.metric = 'rich_rank_improve' then
        v_rank := public.player_rich_rank(p_player);
        continue when v_rank is null or v_rank <= 1;
      end if;
      insert into public.player_missions (player_id, template_key, kind, period_start, target, xp_reward, expires_at, state)
      values (p_player, t.key, v_kind, v_period,
              case when t.scale_with_level and public.mission_is_money_metric(t.metric)
                   then round((t.target_min + floor(random() * (t.target_max - t.target_min + 1))) * v_scale / 100)::bigint * 100
                   else t.target_min + floor(random() * (t.target_max - t.target_min + 1))::bigint end,
              case when coalesce((t.params ->> 'fixedXp')::boolean, false)
                   then t.xp_min + floor(random() * (t.xp_max - t.xp_min + 1))::integer
                   else round((t.xp_min + floor(random() * (t.xp_max - t.xp_min + 1))) * v_xpscale)::integer end,
              v_expires,
              case when t.metric = 'rich_rank_improve' then jsonb_build_object('baseline_rank', v_rank) else '{}'::jsonb end)
      on conflict (player_id, template_key, period_start) do nothing;
      if found then
        v_n := v_n + 1;
      end if;
    end loop;
  end loop;
  if v_n > 0 then
    perform public.mission_refresh_state(p_player);
  end if;
  return v_n;
end;
$$;

update public.mission_templates
   set title = 'Kauf dir ein Grundstück',
       description = 'Deine erste eigene Bleibe: eine Wohnung, ein Haus oder gleich mehr. Einmalig 5.000 XP.',
       xp_min = 2500, xp_max = 2500, chain_order = 1, weight = 100,
       params = params || '{"fixedXp": true}'::jsonb, updated_at = now()
 where key = 'm_home_first';

-- ===== supabase/updates/20261204002800_accessories_pokes.sql =====
-- ===== idempotent copy of migrations/20261204002800_accessories_pokes.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 2800 · Accessories for the pixel figure, the friends plaza, poking friends (ADR-155)
-- =============================================================================
-- * Accessories: catalogue in game_config.accessories (src/config/accessories.ts: key, name, slot, rarity,
--   priceCents, minLevel). A player buys each one once (money to the households, like furniture) and wears at most
--   one per slot. Tables player_accessories (owned) and player_accessories_worn (one row per slot); both internal.
--   RPCs get_accessories(), buy_accessory(request, key) (wears it right away), wear_accessory(request, key, wear).
--   A legendary purchase is news for the friends (feed kind accessory_bought).
-- * Others see it: get_player_card() and friends_json() return the worn keys ("accessories", back to front) and
--   friends_json() also each friend's avatar_key, so the friends plaza can draw the dressed figures.
-- * Poking: poke_friend(request, nickname) between accepted friends sends the notification friend_poke. The same
--   friend again after social.poke.cooldownMinutes (10), at most social.poke.dailyCap (30) pokes in 24 hours.
-- * Errors: accessory_unknown NX130, accessory_locked NX131, accessory_owned NX132, accessory_not_owned NX133,
--   not_friends NX134, poke_too_soon NX135, poke_daily_limit NX136.
-- Idempotent: runs unchanged as supabase/updates/20261204002800_accessories_pokes.sql.

-- ---------------------------------------------------------------------------
-- A. Error keys
-- ---------------------------------------------------------------------------
do $do$
declare
  v_def text := pg_get_functiondef('public.api_error(text)'::regprocedure);
begin
  if position('''poke_daily_limit''' in v_def) = 0 then
    v_def := replace(v_def, $q$    when 'no_shares_left'             then 'NX129'
$q$, $q$    when 'no_shares_left'             then 'NX129'
    when 'accessory_unknown'          then 'NX130'
    when 'accessory_locked'           then 'NX131'
    when 'accessory_owned'            then 'NX132'
    when 'accessory_not_owned'        then 'NX133'
    when 'not_friends'                then 'NX134'
    when 'poke_too_soon'              then 'NX135'
    when 'poke_daily_limit'           then 'NX136'
$q$);
    if position('''poke_daily_limit''' in v_def) = 0 then
      raise exception 'api_error() has an unexpected shape; add the accessory and poke error keys by hand';
    end if;
    execute v_def;
  end if;
end;
$do$;

-- ---------------------------------------------------------------------------
-- B. Notification type
-- ---------------------------------------------------------------------------
insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('friend_poke', 'social', 'Angestupst', 'Ein Freund hat dich angestupst.', 'notif_friend', true, false, false, 276)
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- C. Tables (internal: read and written only by the RPCs below)
-- ---------------------------------------------------------------------------
create table if not exists public.player_accessories (
  player_id        uuid not null references public.profiles (id) on delete cascade,
  accessory_key    text not null check (char_length(accessory_key) between 1 and 64),
  price_paid_cents bigint not null check (price_paid_cents >= 0),
  bought_at        timestamptz not null default now(),
  primary key (player_id, accessory_key)
);
alter table public.player_accessories enable row level security;
revoke all on public.player_accessories from public, anon, authenticated;
grant all on public.player_accessories to service_role;
comment on table public.player_accessories is
  'Accessories a player bought (ADR-155), each once. Internal (RPCs get_accessories, buy_accessory).';

create table if not exists public.player_accessories_worn (
  player_id     uuid not null,
  slot          text not null check (slot in ('back', 'body', 'face', 'head', 'hand', 'pet')),
  accessory_key text not null,
  worn_at       timestamptz not null default now(),
  primary key (player_id, slot),
  foreign key (player_id, accessory_key) references public.player_accessories (player_id, accessory_key) on delete cascade
);
create index if not exists player_accessories_worn_key_idx on public.player_accessories_worn (player_id, accessory_key);
alter table public.player_accessories_worn enable row level security;
revoke all on public.player_accessories_worn from public, anon, authenticated;
grant all on public.player_accessories_worn to service_role;
comment on table public.player_accessories_worn is
  'The accessory a player wears per slot (ADR-155): only owned ones, one per slot. Internal (RPC wear_accessory).';

create table if not exists public.friend_pokes (
  id         bigint generated always as identity primary key,
  poker_id   uuid not null references public.profiles (id) on delete cascade,
  target_id  uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now()
);
create index if not exists friend_pokes_poker_idx on public.friend_pokes (poker_id, created_at desc);
create index if not exists friend_pokes_target_idx on public.friend_pokes (target_id);
alter table public.friend_pokes enable row level security;
revoke all on public.friend_pokes from public, anon, authenticated;
grant all on public.friend_pokes to service_role;
comment on table public.friend_pokes is
  'Pokes between friends (ADR-155), for the pause per friend and the daily cap; older than two days is deleted. Internal.';

-- ---------------------------------------------------------------------------
-- D. Helpers
-- ---------------------------------------------------------------------------
create or replace function public.accessories_cfg()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select value from public.game_config where key = 'accessories'), '{}'::jsonb);
$$;

-- One catalogue entry by key; null if unknown
create or replace function public.accessory_item(p_key text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select x from jsonb_array_elements(coalesce(public.accessories_cfg() -> 'items', '[]'::jsonb)) x
   where x ->> 'key' = p_key
   limit 1;
$$;

-- Worn keys of a player, back to front (the order of accessories.slots)
create or replace function public.player_worn_accessories(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(w.accessory_key order by coalesce(s.ord, 99), w.slot), '[]'::jsonb)
    from public.player_accessories_worn w
    left join lateral (select x.ord from jsonb_array_elements_text(coalesce(public.accessories_cfg() -> 'slots', '[]'::jsonb))
                                          with ordinality as x(slot, ord)
                        where x.slot = w.slot) s on true
   where w.player_id = p_player;
$$;

-- The wardrobe of a player: owned keys (oldest first), worn keys, the portrait
create or replace function public.accessories_state(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'owned', coalesce((select jsonb_agg(a.accessory_key order by a.bought_at, a.accessory_key)
                         from public.player_accessories a where a.player_id = p_player), '[]'::jsonb),
    'worn', public.player_worn_accessories(p_player),
    'avatar_key', (select p.avatar_key from public.profiles p where p.id = p_player));
$$;

-- ---------------------------------------------------------------------------
-- E. RPCs: accessories
-- ---------------------------------------------------------------------------
create or replace function public.get_accessories()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return public.accessories_state(public.require_player());
end;
$$;
comment on function public.get_accessories() is 'RPC: the own wardrobe (ADR-155): owned and worn accessories.';

create or replace function public.buy_accessory(p_request_id uuid, p_key text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_item   jsonb;
  v_price  bigint;
  v_cash   bigint;
begin
  v_player := public.require_player();
  if p_request_id is null or p_key is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_accessory');
  if v_replay is not null then
    return v_replay;
  end if;
  v_item := public.accessory_item(p_key);
  if v_item is null then
    perform public.api_error('accessory_unknown');
  end if;
  if coalesce((select p.level from public.profiles p where p.id = v_player), 1) < coalesce((v_item ->> 'minLevel')::integer, 1) then
    perform public.api_error('accessory_locked');
  end if;
  v_price := (v_item ->> 'priceCents')::bigint;
  if v_price is null or v_price < 0 then
    perform public.api_error('accessory_unknown');
  end if;
  v_cash := public.lock_player_accounts(v_player);
  if exists (select 1 from public.player_accessories a where a.player_id = v_player and a.accessory_key = p_key) then
    perform public.api_error('accessory_owned');
  end if;
  if v_cash < v_price then
    perform public.api_error('insufficient_funds');
  end if;
  if v_price > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('households'),
                                   v_price, 'lifestyle_purchase', 'Accessoire gekauft: ' || coalesce(v_item ->> 'name', p_key),
                                   'accessory', null, 'accessory:' || v_player::text || ':' || p_request_id::text, v_player,
                                   jsonb_build_object('accessory_key', p_key, 'price_cents', v_price));
  end if;
  insert into public.player_accessories (player_id, accessory_key, price_paid_cents) values (v_player, p_key, v_price);
  -- bought to be worn: it goes on right away (replacing what was in the slot)
  insert into public.player_accessories_worn (player_id, slot, accessory_key)
  values (v_player, v_item ->> 'slot', p_key)
  on conflict (player_id, slot) do update set accessory_key = excluded.accessory_key, worn_at = now();
  if coalesce(public.accessories_cfg() -> 'feedRarities', '[]'::jsonb) ? (v_item ->> 'rarity') then
    perform public.feed_post(v_player, 'accessory_bought',
                             jsonb_build_object('key', p_key, 'name', v_item ->> 'name', 'rarity', v_item ->> 'rarity',
                                                'price_cents', v_price),
                             'accessory:' || v_player::text || ':' || p_key);
  end if;
  return public.request_complete(v_player, p_request_id,
    public.accessories_state(v_player) || jsonb_build_object('paid_cents', v_price));
end;
$$;
comment on function public.buy_accessory(uuid, text) is
  'RPC: buys an accessory once (money to the households) and wears it (ADR-155); errors invalid_argument, '
  'accessory_unknown, accessory_locked, accessory_owned, insufficient_funds.';

create or replace function public.wear_accessory(p_request_id uuid, p_key text, p_wear boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_item   jsonb;
begin
  v_player := public.require_player();
  if p_request_id is null or p_key is null or p_wear is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'wear_accessory');
  if v_replay is not null then
    return v_replay;
  end if;
  v_item := public.accessory_item(p_key);
  if v_item is null then
    perform public.api_error('accessory_unknown');
  end if;
  if not exists (select 1 from public.player_accessories a where a.player_id = v_player and a.accessory_key = p_key) then
    perform public.api_error('accessory_not_owned');
  end if;
  if p_wear then
    insert into public.player_accessories_worn (player_id, slot, accessory_key)
    values (v_player, v_item ->> 'slot', p_key)
    on conflict (player_id, slot) do update set accessory_key = excluded.accessory_key, worn_at = now();
  else
    delete from public.player_accessories_worn w where w.player_id = v_player and w.accessory_key = p_key;
  end if;
  return public.request_complete(v_player, p_request_id, public.accessories_state(v_player));
end;
$$;
comment on function public.wear_accessory(uuid, text, boolean) is
  'RPC: puts an owned accessory on (replacing the one in its slot) or takes it off (ADR-155); errors invalid_argument, '
  'accessory_unknown, accessory_not_owned.';

-- ---------------------------------------------------------------------------
-- F. RPC: poke a friend
-- ---------------------------------------------------------------------------
create or replace function public.poke_friend(p_request_id uuid, p_nickname text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_other  uuid;
  v_me     text;
  v_them   text;
  v_cool   integer := greatest(0, coalesce(public.config_double('social', '{poke,cooldownMinutes}', 10), 10)::integer);
  v_cap    integer := greatest(1, coalesce(public.config_double('social', '{poke,dailyCap}', 30), 30)::integer);
  v_last   timestamptz;
  v_count  integer;
  v_id     bigint;
  v_lines  text[] := array[
    'Stups zurück, bevor es peinlich wird.',
    'Das war ein freundschaftlicher Stups. Vermutlich.',
    'Schau mal vorbei, dein Depot vermisst dich.',
    'Pssst! Jemand denkt an dich.',
    'Stups! Du bist dran.'];
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'poke_friend');
  if v_replay is not null then
    return v_replay;
  end if;
  v_other := public.friend_target(v_player, p_nickname);
  if not exists (select 1 from public.friendships f
                  where f.status = 'accepted'
                    and least(f.requester_id, f.addressee_id) = least(v_player, v_other)
                    and greatest(f.requester_id, f.addressee_id) = greatest(v_player, v_other)) then
    perform public.api_error('not_friends');
  end if;
  -- one poke of the same player at a time
  select p.nickname into v_me from public.profiles p where p.id = v_player for update;
  select p.nickname into v_them from public.profiles p where p.id = v_other;
  select max(x.created_at) into v_last from public.friend_pokes x where x.poker_id = v_player and x.target_id = v_other;
  if v_last is not null and v_last > now() - make_interval(mins => v_cool) then
    perform public.api_error('poke_too_soon');
  end if;
  select count(*) into v_count from public.friend_pokes x where x.poker_id = v_player and x.created_at > now() - interval '24 hours';
  if v_count >= v_cap then
    perform public.api_error('poke_daily_limit');
  end if;
  insert into public.friend_pokes (poker_id, target_id) values (v_player, v_other) returning id into v_id;
  delete from public.friend_pokes x where x.poker_id = v_player and x.created_at < now() - interval '2 days';
  perform public.social_notify(v_other, 'friend_poke', v_me || ' hat dich angestupst! 👉',
                               v_lines[1 + floor(random() * array_length(v_lines, 1))::integer],
                               jsonb_build_object('nickname', v_me), '/players/' || v_me, 'poke:' || v_id::text);
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'nickname', v_them,
    'poked_at', now(),
    'next_at', now() + make_interval(mins => v_cool),
    'left_today', greatest(0, v_cap - v_count - 1)));
end;
$$;
comment on function public.poke_friend(uuid, text) is
  'RPC: pokes a friend (ADR-155): notification friend_poke with a link to the own profile; errors invalid_argument, '
  'player_not_found, not_friends, poke_too_soon, poke_daily_limit.';

-- ---------------------------------------------------------------------------
-- G. Others see the figure: friends list and player card
-- ---------------------------------------------------------------------------
create or replace function public.friends_json(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'friends', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level,
                                          'since', coalesce(f.responded_at, f.updated_at),
                                          'online', coalesce(p.last_active_at > public.game_now() - make_interval(
                                                      mins => coalesce(public.config_double('social', '{onlineMinutes}', 10), 10)::integer), false),
                                          'last_active_at', p.last_active_at,
                                          'avatar_key', p.avatar_key,
                                          'accessories', public.player_worn_accessories(p.id))
                       order by coalesce(p.last_active_at > public.game_now() - make_interval(
                                  mins => coalesce(public.config_double('social', '{onlineMinutes}', 10), 10)::integer), false) desc,
                                lower(p.nickname), p.id)
        from public.friendships f
        join public.profiles p on p.id = case when f.requester_id = p_player then f.addressee_id else f.requester_id end
       where f.status = 'accepted' and p_player in (f.requester_id, f.addressee_id) and not p.is_deactivated), '[]'::jsonb),
    'incoming', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.requester_id
       where f.status = 'pending' and f.addressee_id = p_player and not p.is_deactivated), '[]'::jsonb),
    'outgoing', coalesce((
      select jsonb_agg(jsonb_build_object('nickname', p.nickname, 'tag', p.tag, 'level', p.level, 'at', f.updated_at)
                       order by f.updated_at desc, p.id)
        from public.friendships f join public.profiles p on p.id = f.addressee_id
       where f.status = 'pending' and f.requester_id = p_player and not p.is_deactivated), '[]'::jsonb));
$$;

do $do$
declare
  v_def text := pg_get_functiondef('public.get_player_card(text)'::regprocedure);
  v_old text := $t$    'trust',           public.player_trust(p.id));$t$;
  v_new text := $t$    'accessories',     public.player_worn_accessories(p.id),
    'trust',           public.player_trust(p.id));$t$;
begin
  if position('player_worn_accessories' in v_def) = 0 then
    if position(v_old in v_def) = 0 then
      raise exception 'get_player_card() has an unexpected shape; add the accessories by hand';
    end if;
    execute replace(v_def, v_old, v_new);
  end if;
end;
$do$;

-- ---------------------------------------------------------------------------
-- H. Account reset and deletion forget the wardrobe and the pokes; the feed names the purchase
-- ---------------------------------------------------------------------------
do $do$
declare
  v_def text := pg_get_functiondef('public.account_wipe(uuid, text)'::regprocedure);
  v_old text := $t$('player_homes', 'player_id'), ('trust_events', 'player_id')$t$;
  v_new text := $t$('player_homes', 'player_id'), ('trust_events', 'player_id'),
             ('player_accessories_worn', 'player_id'), ('player_accessories', 'player_id'), ('friend_pokes', 'poker_id')$t$;
begin
  if position('player_accessories_worn' in v_def) = 0 then
    if position(v_old in v_def) = 0 then
      raise exception 'account_wipe() has an unexpected shape; add the accessory tables by hand';
    end if;
    execute replace(v_def, v_old, v_new);
  end if;
end;
$do$;

do $do$
declare
  v_def text := pg_get_functiondef('public.feed_item_label(text, jsonb)'::regprocedure);
  v_old text := $t$    when 'car_bought' then 'Neues Auto'$t$;
  v_new text := $t$    when 'car_bought' then 'Neues Auto'
    when 'accessory_bought' then coalesce(p_payload ->> 'name', 'Accessoire') || ' gekauft'$t$;
begin
  if position('accessory_bought' in v_def) = 0 and position(v_old in v_def) > 0 then
    execute replace(v_def, v_old, v_new);
  end if;
end;
$do$;

-- ---------------------------------------------------------------------------
-- I. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.accessories_cfg()', 'public.accessory_item(text)', 'public.player_worn_accessories(uuid)',
    'public.accessories_state(uuid)', 'public.get_accessories()', 'public.buy_accessory(uuid, text)',
    'public.wear_accessory(uuid, text, boolean)', 'public.poke_friend(uuid, text)', 'public.friends_json(uuid)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.get_accessories()', 'public.buy_accessory(uuid, text)', 'public.wear_accessory(uuid, text, boolean)',
    'public.poke_friend(uuid, text)'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;

-- ===== supabase/updates/20261204003200_news_audience.sql =====
-- ===== idempotent copy of migrations/20261204003200_news_audience.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 3200 · The studio audience of NEXA Nachrichten and players on the TV with their figure (ADR-157)
-- =============================================================================
-- * player_figure_json(player): the public look of a player, {nickname, avatar_key, accessories}; one helper for
--   every place that draws someone's dressed figure (internal, never with an id).
-- * get_news_show() returns "audience": everyone who watched within the last 20 seconds (the caller included), as
--   their figure with "friend" and "me", the caller first, then friends, then the others by name; at most
--   newsShow.audience.max.
-- * Segments about a player (loser, winner, gossip, scandal/hype of a founder, the creator of an NFT) carry that
--   player's "figure", read when the show is fetched, so it is always the current look.
-- * news_show_chat_json() marks the lines of the made-up viewers ("bot"), so the client gives them a figure of
--   their own.
-- Idempotent: runs unchanged as supabase/updates/20261204003200_news_audience.sql.

-- The public look of a player: nickname, portrait, worn accessories (back to front); null when unknown or gone.
create or replace function public.player_figure_json(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object('nickname', p.nickname, 'avatar_key', p.avatar_key,
                            'accessories', public.player_worn_accessories(p.id))
    from public.profiles p
   where p.id = p_player and not p.is_deactivated;
$$;
comment on function public.player_figure_json(uuid) is
  'Internal: a player''s dressed figure for others (ADR-157): nickname, avatar_key, accessories; never the id.';

-- The chat: players and made-up viewers ("bot"); lines of the latter appear when their time has come.
create or replace function public.news_show_chat_json(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'nickname', m.nickname, 'body', m.body, 'at', m.created_at,
                                               'mine', coalesce(m.player_id = p_player, false),
                                               'bot', m.bot_name is not null)
                            order by m.created_at, m.id), '[]'::jsonb)
    from (select x.id, x.body, x.created_at, x.player_id, x.bot_name, coalesce(x.bot_name, p.nickname) as nickname
            from public.news_show_messages x left join public.profiles p on p.id = x.player_id
           where x.created_at > public.game_now() - interval '75 minutes' and x.created_at <= public.game_now()
             and coalesce(x.bot_name, p.nickname) is not null
           order by x.created_at desc, x.id desc
           limit coalesce((public.news_show_cfg() #>> '{chat,history}')::integer, 60)) m;
$$;

-- Who watches right now, as figures: the caller first, then friends, then the others (by name, so nobody jumps).
create or replace function public.news_show_audience_json(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(public.player_figure_json(a.player_id)
                            || jsonb_build_object('friend', a.friend, 'me', a.me)
                            order by a.me desc, a.friend desc, lower(a.nickname), a.player_id), '[]'::jsonb)
    from (select v.player_id, p.nickname, v.player_id = p_player as me,
                 exists (select 1 from public.friendships f
                          where f.status = 'accepted'
                            and ((f.requester_id = p_player and f.addressee_id = v.player_id)
                              or (f.addressee_id = p_player and f.requester_id = v.player_id))) as friend
            from public.news_show_viewers v
            join public.profiles p on p.id = v.player_id and not p.is_deactivated
           where v.seen_at > public.game_now() - interval '20 seconds'
           order by me desc, friend desc, lower(p.nickname), v.player_id
           limit greatest(1, coalesce((public.news_show_cfg() #>> '{audience,max}')::integer, 12))) a;
$$;

create or replace function public.get_news_show()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg      jsonb := public.news_show_cfg();
  v_player uuid := public.require_player();
  v_now    timestamptz := public.game_now();
  v_hour   timestamptz := date_trunc('hour', public.game_now());
  v_wait   interval := make_interval(mins => coalesce((cfg ->> 'waitMinutes')::integer, 10));
  s        public.news_shows;
  u        public.news_shows;
begin
  -- I am watching
  insert into public.news_show_viewers (player_id, seen_at) values (v_player, v_now)
  on conflict (player_id) do update set seen_at = excluded.seen_at
   where public.news_show_viewers.seen_at < excluded.seen_at - interval '4 seconds';
  -- the draft may be missing when the job is late; this hour's show starts with its first viewer
  if not exists (select 1 from public.news_shows x
                  where x.airs_at = case when v_now < v_hour + v_wait then v_hour else v_hour + interval '1 hour' end) then
    perform public.news_show_run_due(v_now);
  end if;
  select * into u from public.news_shows x where x.airs_at = v_hour and x.status = 'scheduled';
  if u.id is not null and v_now < v_hour + v_wait then
    if public.news_show_start(u.id, v_now) then
      perform public.news_show_after_start(u.id, v_now);
    end if;
  end if;
  -- the show to watch: the last one that aired, while it can be replayed
  select * into s from public.news_shows x
   where x.status = 'aired'
     and x.started_at > v_now - make_interval(mins => coalesce((cfg ->> 'replayMinutes')::integer, 55))
   order by x.airs_at desc limit 1;
  select * into u from public.news_shows x where x.status = 'scheduled' and x.airs_at > v_now order by x.airs_at limit 1;
  return jsonb_build_object(
    'now', v_now,
    'next_airs_at', coalesce(u.airs_at, v_hour + interval '1 hour'),
    'viewers', (select count(*) from public.news_show_viewers v where v.seen_at > v_now - interval '20 seconds'),
    'audience', public.news_show_audience_json(v_player),
    'upcoming', case when u.id is null then null else jsonb_build_object(
                  'id', u.id, 'airs_at', u.airs_at,
                  'needs_script', u.writer = 'mini' and u.ai_requested_at is null) end,
    'show', case when s.id is null then null else jsonb_build_object(
              'id', s.id, 'airs_at', s.airs_at, 'started_at', s.started_at, 'writer', s.writer,
              'segments', coalesce((select jsonb_agg(jsonb_build_object('kind', x ->> 'kind', 'mood', coalesce(x ->> 'mood', 'neutral'),
                                                                        'headline', x ->> 'headline',
                                                                        'text', x ->> 'text', 'effects', x -> 'effects')
                                                     || case when fig.f is null then '{}'::jsonb
                                                             else jsonb_build_object('figure', fig.f) end
                                                      order by ord)
                                      from jsonb_array_elements(s.segments) with ordinality t(x, ord)
                                      left join lateral (
                                        select public.player_figure_json((x -> 'subject' ->> 'player_id')::uuid) as f
                                         where x -> 'subject' ->> 'player_id' is not null) fig on true),
                                   '[]'::jsonb)) end,
    'chat', public.news_show_chat_json(v_player));
end;
$$;

revoke all on function public.player_figure_json(uuid) from public, anon, authenticated;
revoke all on function public.news_show_audience_json(uuid) from public, anon, authenticated;
revoke all on function public.news_show_chat_json(uuid) from public, anon, authenticated;
grant execute on function public.player_figure_json(uuid) to service_role;
revoke all on function public.get_news_show() from public, anon;
grant execute on function public.get_news_show() to authenticated;
comment on function public.get_news_show() is
  'RPC: NEXA Nachrichten (ADR-150/152/157): the show to watch, the next airing, viewers, the studio audience as '
  'figures, segments (with the figure of the player they are about) and the live chat; starts this hour''s show for '
  'its first viewer.';

-- ===== supabase/updates/20261204003300_company_floor.sql =====
-- ===== idempotent copy of migrations/20261204003300_company_floor.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 3300 · The company floor: everybody at work as their dressed figure, with speech bubbles (ADR-156)
-- =============================================================================
-- get_company_floor() returns the workplace of the caller for the pixel scene on the job page and the company page:
-- * a player company (the chat company, founder or active employee): the founder and every active employee with
--   portrait (avatar_key), worn accessories (back to front), role founder/employee, job title, online (active in the
--   last social.onlineMinutes, default 10), me, and the newest own player message of the last startups.chat
--   .bubbleSeconds (default 120) as last_message {body, at}; system lines never count. Writing goes through
--   post_company_message() (same rules and limits), so the scene and the chat show the same words.
-- * an AI company (the caller has an active job there): the caller and up to startups.chat.floorMaxMembers - 1
--   coworkers with an active job at the same company (online first), without chat and without bubbles.
-- * otherwise company null and no members.
-- No ids leave the server: nicknames only, like friends_json().
-- Idempotent: runs unchanged as supabase/updates/20261204003300_company_floor.sql.

create or replace function public.company_floor_member_json(p_player uuid, p_viewer uuid, p_role text, p_title text,
                                                            p_company uuid, p_bubbles boolean)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'nickname', p.nickname,
    'avatar_key', p.avatar_key,
    'accessories', public.player_worn_accessories(p.id),
    'role', p_role,
    'title', p_title,
    'online', coalesce(p.last_active_at > public.game_now() - make_interval(
                mins => coalesce(public.config_double('social', '{onlineMinutes}', 10), 10)::integer), false),
    'me', p.id = p_viewer,
    'last_message', case when p_bubbles then (
      select jsonb_build_object('body', m.body, 'at', m.created_at)
        from public.company_messages m
       where m.company_id = p_company and m.author_id = p.id and m.kind = 'player'
         and m.created_at > now() - make_interval(
               secs => coalesce(public.config_double('startups', '{chat,bubbleSeconds}', 120), 120))
       order by m.id desc
       limit 1) end)
    from public.profiles p
   where p.id = p_player;
$$;
revoke all on function public.company_floor_member_json(uuid, uuid, text, text, uuid, boolean) from public, anon, authenticated;
grant execute on function public.company_floor_member_json(uuid, uuid, text, text, uuid, boolean) to service_role;

create or replace function public.get_company_floor()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player  uuid := public.require_player();
  v_company uuid := public.chat_company_of(v_player);
  v_max     integer := greatest(2, coalesce(public.config_double('startups', '{chat,floorMaxMembers}', 24), 24)::integer);
  v_secs    integer := coalesce(public.config_double('startups', '{chat,bubbleSeconds}', 120), 120)::integer;
  v_ai      boolean := false;
  v_online  interval := make_interval(mins => coalesce(public.config_double('social', '{onlineMinutes}', 10), 10)::integer);
  c         public.companies;
  v_members jsonb;
  v_workers integer := 0;
begin
  if v_company is null then
    select j.company_id into v_company
      from public.player_jobs j join public.companies co on co.id = j.company_id and co.is_ai
     where j.player_id = v_player and j.status = 'active'
     limit 1;
    v_ai := v_company is not null;
  end if;
  if v_company is null then
    return jsonb_build_object('company', null, 'chat', false, 'ai_workers', 0, 'bubble_seconds', v_secs,
                              'members', '[]'::jsonb);
  end if;
  select * into c from public.companies where id = v_company;

  if v_ai then
    select coalesce(jsonb_agg(public.company_floor_member_json(x.player_id, v_player, 'employee', x.title, v_company, false)
                              order by x.ord), '[]'::jsonb)
      into v_members
      from (select j.player_id, j.title,
                   row_number() over (order by (j.player_id = v_player) desc,
                                               coalesce(p.last_active_at > public.game_now() - v_online, false) desc,
                                               p.last_active_at desc nulls last, lower(p.nickname), j.player_id) as ord
              from public.player_jobs j join public.profiles p on p.id = j.player_id
             where j.company_id = v_company and j.status = 'active' and not p.is_deactivated) x
     where x.ord <= v_max;
  else
    select coalesce(pc.ai_workers, 0) into v_workers from public.player_companies pc where pc.company_id = v_company;
    select coalesce(jsonb_agg(public.company_floor_member_json(x.player_id, v_player, x.role, x.title, v_company, true)
                              order by x.ord, x.nick, x.player_id), '[]'::jsonb)
      into v_members
      from (select pc.founder_id as player_id, 'founder' as role, null::text as title, 0 as ord, ''::text as nick
              from public.player_companies pc
             where pc.company_id = v_company and pc.status = 'active' and pc.founder_id is not null
            union all
            select j.player_id, 'employee', j.title, 1, lower(p.nickname)
              from public.player_jobs j join public.profiles p on p.id = j.player_id
             where j.company_id = v_company and j.status = 'active' and not p.is_deactivated) x;
  end if;

  return jsonb_build_object(
    'company', jsonb_build_object('name', c.name, 'color', c.brand_color, 'kind', case when v_ai then 'ai' else 'player' end,
                                  'logo', case when v_ai then null else public.company_logo(c.id) end),
    'chat', not v_ai,
    'ai_workers', v_workers,
    'bubble_seconds', v_secs,
    'members', v_members);
end;
$$;
revoke all on function public.get_company_floor() from public, anon;
grant execute on function public.get_company_floor() to authenticated, service_role;
comment on function public.get_company_floor() is
  'RPC: the workplace of the caller as a pixel scene (ADR-156): company {name, color, kind, logo}, chat, ai_workers, '
  'bubble_seconds and members [{nickname, avatar_key, accessories, role, title, online, me, last_message}]; no ids.';

-- ===== supabase/updates/20261204003500_missions_level_features.sql =====
-- ===== idempotent copy of migrations/20261204003500_missions_level_features.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 3500 · Harder missions with the level, missions for the new features (ADR-159)
-- =============================================================================
-- * missions_assign(): counted daily and weekly missions (and quick ones counting more than one) scale their target
--   with the level: x (1 + progression.missionCountScalePerLevel x (level - 1)), at most missionCountScaleMax.
--   Money targets keep their own scale (missionTargetScale*), XP keeps missionXpScale*.
-- * New metrics, fed by triggers so no RPC is redefined: accessory_bought, accessory_legendary, accessory_worn,
--   friend_poke, news_chat, company_chat. mission_doable() knows their preconditions; requirement "accessory".
-- * 19 new mission templates (quick, daily, weekly, milestone) for wardrobe, pokes, the news chat and the team chat.
-- Idempotent: runs unchanged as supabase/updates/20261204003500_missions_level_features.sql.

-- requirement "accessory": owns at least one accessory (wearing another one is possible)
do $do$
declare
  v_def text := pg_get_functiondef('public.mission_requirement_ok(uuid, text)'::regprocedure);
  v_old text := $t$           else false end;$t$;
  v_new text := $t$           when 'accessory' then exists (select 1 from public.player_accessories a where a.player_id = p_player)
           else false end;$t$;
begin
  if position('''accessory''' in v_def) = 0 then
    execute replace(v_def, v_old, v_new);
  end if;
end;
$do$;

create or replace function public.mission_doable(p_player uuid, p_key text, p_metric text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  with co as (
    select pc.company_id, pc.ai_workers, c.max_employees, public.company_headcount(pc.company_id) as heads
      from public.player_companies pc join public.companies c on c.id = pc.company_id
     where pc.founder_id = p_player and pc.status = 'active'
     limit 1
  ), home as (
    select h.tier, coalesce((select (t ->> 'garageSlots')::integer
                               from jsonb_array_elements(public.config_jsonb('property', '{tiers}')) t
                              where t ->> 'key' = h.tier), 0) as garage,
           (select max(ord) from jsonb_array_elements(public.config_jsonb('property', '{tiers}')) with ordinality x(t, ord)) as top,
           (select ord from jsonb_array_elements(public.config_jsonb('property', '{tiers}')) with ordinality x(t, ord)
             where t ->> 'key' = h.tier) as pos
      from public.player_homes h where h.player_id = p_player
  )
  select case
    -- hiring needs a free place in the company; the "first" one only for who never had an AI worker
    when p_metric = 'ai_worker_hired' then
      exists (select 1 from co where co.heads < co.max_employees
                                 and (p_key <> 'm_first_ai_worker' or co.ai_workers = 0))
    when p_metric = 'job_posted' then
      exists (select 1 from co where co.heads < co.max_employees
                                 and (p_key <> 'm_first_posting'
                                      or not exists (select 1 from public.job_postings j where j.company_id = co.company_id)))
    -- property: buy one only without a home, move only below the top tier, cars only with a free garage place
    when p_metric = 'home_bought' then not exists (select 1 from home)
    when p_metric = 'home_upgraded' then exists (select 1 from home where home.pos < home.top)
    when p_metric = 'car_bought' then
      exists (select 1 from home where home.garage > (select count(*) from public.player_cars c where c.player_id = p_player))
    when p_metric in ('furniture_bought', 'furniture_placed') then exists (select 1 from home)
    -- ADR-159: poking needs a friend; the team chat a company; wearing something needs something to wear
    when p_metric = 'friend_poke' then exists (select 1 from public.friendships f
                                                where f.status = 'accepted' and p_player in (f.requester_id, f.addressee_id))
    when p_metric = 'company_chat' then public.mission_requirement_ok(p_player, 'team')
    when p_key = 'm_first_accessory' then not exists (select 1 from public.player_accessories a where a.player_id = p_player)
    -- "your first ..." only for who has not done it yet
    when p_key = 'm_first_skill' then not exists (select 1 from public.player_skills s where s.player_id = p_player)
    when p_key = 'm_first_move' then not exists (select 1 from public.company_moves m where m.started_by = p_player)
    when p_key = 'm_first_trade' then not exists (select 1 from public.trades t where t.player_id = p_player)
    when p_key = 'm_art_paint' then not exists (select 1 from public.artworks a where a.creator_id = p_player)
    when p_key = 'm_first_bond' then not exists (select 1 from public.trades t join public.securities s on s.id = t.security_id
                                                  where t.player_id = p_player and s.kind = 'bond')
    else true end;
$$;
revoke all on function public.mission_doable(uuid, text, text) from public, anon, authenticated;
grant execute on function public.mission_doable(uuid, text, text) to service_role;

create or replace function public.missions_assign(p_player uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_prog     jsonb := coalesce(public.config_jsonb('progression'), '{}'::jsonb);
  v_now      timestamptz := public.game_now();
  v_today    date := (public.game_now() at time zone 'Europe/Berlin')::date;
  v_monday   date;
  v_level    integer;
  v_scale    double precision;
  v_xpscale  double precision;
  v_cscale   double precision;
  v_need     integer;
  v_n        integer := 0;
  v_kind     text;
  v_period   date;
  v_expires  timestamptz;
  v_rank     integer;
  t          record;
begin
  v_monday := v_today - (extract(isodow from v_today)::integer - 1);
  select p.level into v_level from public.profiles p where p.id = p_player for update;
  if v_level is null then
    return 0;
  end if;
  v_scale := least(public.cfg_num(v_prog, '{missionTargetScaleMax}', 5),
                   1 + public.cfg_num(v_prog, '{missionTargetScalePerLevel}', 0.2) * (v_level - 1));
  -- ADR-159: counted missions get harder with the level
  v_cscale := least(public.cfg_num(v_prog, '{missionCountScaleMax}', 1),
                    1 + public.cfg_num(v_prog, '{missionCountScalePerLevel}', 0) * (v_level - 1));
  -- ADR-142: mission XP grows with the level, so missions stay worth it as levels need more XP
  v_xpscale := least(public.cfg_num(v_prog, '{missionXpScaleMax}', 1),
                     1 + public.cfg_num(v_prog, '{missionXpScalePerLevel}', 0) * (v_level - 1));

  -- ADR-154: a mission nobody can finish any more (the company is full, the home is bought) makes room for another
  update public.player_missions m set status = 'expired', expires_at = least(coalesce(m.expires_at, v_now), v_now)
    from public.mission_templates mt
   where mt.key = m.template_key and m.player_id = p_player and m.status = 'active' and m.progress = 0
     and m.kind in ('quick', 'milestone') and mt.mode <> 'state'
     and not public.mission_doable(p_player, mt.key, mt.metric);

  -- expire what ran out
  update public.player_missions set status = 'expired'
   where player_id = p_player and status in ('active', 'completed') and expires_at is not null and expires_at <= v_now;

  foreach v_kind in array array['quick', 'daily', 'weekly', 'milestone'] loop
    if v_kind = 'quick' then
      v_need := public.cfg_num(v_prog, '{xpSources,quickMission,active}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'quick' and m.status in ('active', 'completed'));
      v_period := v_today; v_expires := null;
    elsif v_kind = 'daily' then
      v_need := public.cfg_num(v_prog, '{xpSources,dailyMission,perDay}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'daily' and m.period_start = v_today);
      v_period := v_today; v_expires := ((v_today + 1)::timestamp) at time zone 'Europe/Berlin';
    elsif v_kind = 'weekly' then
      v_need := public.cfg_num(v_prog, '{xpSources,weeklyMission,perWeek}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'weekly' and m.period_start = v_monday);
      v_period := v_monday; v_expires := ((v_monday + 7)::timestamp) at time zone 'Europe/Berlin';
    else
      v_need := public.cfg_num(v_prog, '{xpSources,milestoneMission,visible}', 3)::integer
              - (select count(*) from public.player_missions m where m.player_id = p_player and m.kind = 'milestone' and m.status in ('active', 'completed'));
      v_period := date '2000-01-01'; v_expires := null;
    end if;
    continue when v_need <= 0;

    for t in
      select mt.*
        from public.mission_templates mt
       where mt.kind = v_kind and mt.mode is not null and mt.is_active
         and mt.min_level <= v_level
         and (not (mt.params ? 'unlock') or v_level >= public.unlock_level(mt.params ->> 'unlock'))
         and public.mission_requirement_ok(p_player, mt.params ->> 'requires')
         and public.mission_doable(p_player, mt.key, mt.metric)
         and not exists (select 1 from public.player_missions m
                          where m.player_id = p_player and m.template_key = mt.key
                            and (m.period_start = v_period
                                 or (v_kind = 'quick' and (m.status in ('active', 'completed') or m.created_at > v_now - interval '24 hours'))
                                 or v_kind = 'milestone'))
       order by case when v_kind = 'milestone' then mt.chain_order end,
                -ln(1 - random()) / greatest(mt.weight, 1)
       limit v_need
    loop
      if t.metric = 'rich_rank_improve' then
        v_rank := public.player_rich_rank(p_player);
        continue when v_rank is null or v_rank <= 1;
      end if;
      insert into public.player_missions (player_id, template_key, kind, period_start, target, xp_reward, expires_at, state)
      values (p_player, t.key, v_kind, v_period,
              case when t.scale_with_level and public.mission_is_money_metric(t.metric)
                   then round((t.target_min + floor(random() * (t.target_max - t.target_min + 1))) * v_scale / 100)::bigint * 100
                   when t.mode in ('count', 'sum') and not public.mission_is_money_metric(t.metric)
                        and (v_kind in ('daily', 'weekly') or (v_kind = 'quick' and t.target_min >= 2))
                   then greatest(t.target_min, round((t.target_min + floor(random() * (t.target_max - t.target_min + 1))) * v_cscale))::bigint
                   else t.target_min + floor(random() * (t.target_max - t.target_min + 1))::bigint end,
              case when coalesce((t.params ->> 'fixedXp')::boolean, false)
                   then t.xp_min + floor(random() * (t.xp_max - t.xp_min + 1))::integer
                   else round((t.xp_min + floor(random() * (t.xp_max - t.xp_min + 1))) * v_xpscale)::integer end,
              v_expires,
              case when t.metric = 'rich_rank_improve' then jsonb_build_object('baseline_rank', v_rank) else '{}'::jsonb end)
      on conflict (player_id, template_key, period_start) do nothing;
      if found then
        v_n := v_n + 1;
      end if;
    end loop;
  end loop;
  if v_n > 0 then
    perform public.mission_refresh_state(p_player);
  end if;
  return v_n;
end;
$$;

-- ---------------------------------------------------------------------------
-- Mission events from the new features (triggers: the RPCs stay as they are)
-- ---------------------------------------------------------------------------
create or replace function public.mission_feature_events()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_rarity text;
begin
  if tg_table_name = 'player_accessories' then
    perform public.mission_event(new.player_id, 'accessory_bought', 1, new.accessory_key);
    select x ->> 'rarity' into v_rarity
      from jsonb_array_elements(coalesce(public.config_jsonb('accessories', '{items}'), '[]'::jsonb)) x
     where x ->> 'key' = new.accessory_key;
    if v_rarity in ('legendary', 'mythic') then
      perform public.mission_event(new.player_id, 'accessory_legendary', 1, new.accessory_key);
    end if;
  elsif tg_table_name = 'player_accessories_worn' then
    if tg_op = 'INSERT' or new.accessory_key is distinct from old.accessory_key then
      perform public.mission_event(new.player_id, 'accessory_worn', 1, new.accessory_key);
    end if;
  elsif tg_table_name = 'friend_pokes' then
    perform public.mission_event(new.poker_id, 'friend_poke', 1, new.target_id::text);
  elsif tg_table_name = 'news_show_messages' then
    if new.player_id is not null then
      perform public.mission_event(new.player_id, 'news_chat', 1, null);
    end if;
  elsif tg_table_name = 'company_messages' then
    if new.kind = 'player' and new.author_id is not null then
      perform public.mission_event(new.author_id, 'company_chat', 1, null);
    end if;
  end if;
  return new;
end;
$$;
revoke all on function public.mission_feature_events() from public, anon, authenticated;
comment on function public.mission_feature_events() is
  'Trigger: mission events of the wardrobe, pokes, news chat and team chat (ADR-159).';

drop trigger if exists mission_events on public.player_accessories;
create trigger mission_events after insert on public.player_accessories
  for each row execute function public.mission_feature_events();
drop trigger if exists mission_events on public.player_accessories_worn;
create trigger mission_events after insert or update of accessory_key on public.player_accessories_worn
  for each row execute function public.mission_feature_events();
drop trigger if exists mission_events on public.friend_pokes;
create trigger mission_events after insert on public.friend_pokes
  for each row execute function public.mission_feature_events();
drop trigger if exists mission_events on public.news_show_messages;
create trigger mission_events after insert on public.news_show_messages
  for each row execute function public.mission_feature_events();
drop trigger if exists mission_events on public.company_messages;
create trigger mission_events after insert on public.company_messages
  for each row execute function public.mission_feature_events();

